import{c as a,Q as t,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Token Economics for LLM Agents: A Dual-View Study from Computing and Economics","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.09104","title":"Token Economics for LLM Agents: A Dual-View Study from Computing and Economics","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2605.09104,"authors":["Yuxi Chen","Junming Chen","Chenyu He","Yiwei Li","Yicheng Ji","Yifan Wu","Dingyu Yang","Lansong Diao","Lidan Shou","Hongliang Zhang","Huan Li","Gang Chen"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2605.09104v1","pdf_path":"pdfs/2605.09104.pdf","published_date":"2026-05-09T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-09-token-economics-llm-agents-dual-view-2605-09104.md","filePath":"research/papers/2026-05-09-token-economics-llm-agents-dual-view-2605-09104.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-05-09-token-economics-llm-agents-dual-view-2605-09104.md"};function r(s,e,c,l,d,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="token-economics-for-llm-agents-a-dual-view-study-from-computing-and-economics" tabindex="-1">Token Economics for LLM Agents: A Dual-View Study from Computing and Economics <a class="header-anchor" href="#token-economics-for-llm-agents-a-dual-view-study-from-computing-and-economics" aria-label="Permalink to &quot;Token Economics for LLM Agents: A Dual-View Study from Computing and Economics&quot;">​</a></h1><p><strong>Authors</strong>: Yuxi Chen et al.（12 位作者） <strong>Published</strong>: May 9, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.09104" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.09104</a> · <a href="https://arxiv.org/html/2605.09104v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2605.09104 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.09104" target="_blank" rel="noreferrer">research/papers/pdfs/2605.09104.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>As LLM agents evolve, tokens have emerged as the core economic primitives of Agentic AI. However, their exponential consumption introduces severe computational, collaborative, and security bottlenecks. Current surveys remain fragmented across system optimization, architecture design, and trust, lacking a unified framework to evaluate the fundamental trade-off between output quality and economic cost. To bridge this gap, this survey presents the first comprehensive survey of Token Economics. By unifying computer science and economics, we conceptualize tokens as production factors, exchange mediums, and units of account. We synthesize existing literature across a four-dimensional taxonomy: (1) Micro-level (Single Agent): Optimizing budget-constrained factor substitution via neoclassical firm theory. (2) Meso-level (Multi-Agent Systems): Minimizing collaboration friction using transaction cost and principal-agent theories. (3) Macro-level (Agent Ecosystems): Addressing congestion externalities and pricing via mechanism design. (4) Security: Internalizing adversarial threats as endogenous economic constraints. Finally, we outline frontier directions, including differentiable token budgets and dynamic markets, to lay the theoretical foundation for scalable next-generation agent systems.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>首個 Token Economics 綜述：把 token 概念化為生產要素、交換媒介、記帳單位，統一 CS 與經濟學視角</li><li>四維分類法：Micro（單 agent 預算約束的要素替代）/ Meso（MAS 用交易成本與 principal-agent 理論降協作摩擦）/ Macro（生態系壅塞外部性與定價機制設計）/ Security（對抗威脅內生化為經濟約束）</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>綜述性論文，無單一實驗數字；提出 differentiable token budgets、dynamic markets 等前沿方向</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>理論框架綜述，工程可操作性需自行轉譯</li><li>經濟學類比（firm theory 等）的解釋力上限未經實證檢驗</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>principal-agent theory 視角精準對應 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的 handoff 固定開銷計算與 benefit-gated 委派——委派決策本質是交易成本比較，可為 `core.md §PROPOSE 委派``） 提供理論詞彙。</li><li>Micro-level「budget-constrained factor substitution」即檔位經濟（cost/quality/ceiling）的理論化；與 <code>.claude/skills/output-compress</code> 檔位上限、FinOps 判斷框架直接共鳴。</li></ul>',16)])])}const g=a(i,[["render",r]]);export{h as __pageData,g as default};
